using UnityEngine;

public class ActiveRagdoll : MonoBehaviour
{
 public Rigidbody[] rigidbodies;
 public Collider[] colliders;
 public Animator animator;
 public float torqueMultiplier = 1.0f;
 public float forceMultiplier = 1.0f;

 private bool isActive = true;

 void Start()
 {
 // Disable all rigidbodies and colliders
 foreach (Rigidbody rb in rigidbodies)
 {
 rb.isKinematic = true;
 }

 foreach (Collider collider in colliders)
 {
 collider.enabled = false;
 }
 }

 void Update()
 {
 if (Input.GetKeyDown(KeyCode.Space))
 {
 if (isActive)
 {
 // Enable all rigidbodies and colliders
 foreach (Rigidbody rb in rigidbodies)
 {
 rb.isKinematic = false;
 }

 foreach (Collider collider in colliders)
 {
 collider.enabled = true;
 }

 // Deactivate the animator
 animator.enabled = false;

 isActive = false;
 }
 else
 {
 // Disable all rigidbodies and colliders
 foreach (Rigidbody rb in rigidbodies)
 {
 rb.isKinematic = true;
 }

 foreach (Collider collider in colliders)
 {
 collider.enabled = false;
 }

 // Activate the animator
 animator.enabled = true;

 isActive = true;
 }
 }
 }

 void FixedUpdate()
 {
 if (!isActive)
 {
 // Apply torque and force to the rigidbodies
 float horizontalInput = Input.GetAxis("Horizontal");
 float verticalInput = Input.GetAxis("Vertical");

 foreach (Rigidbody rb in rigidbodies)
 {
 rb.AddTorque(transform.up * horizontalInput * torqueMultiplier);
 rb.AddTorque(transform.right * -verticalInput * torqueMultiplier);
 rb.AddForce(transform.forward * verticalInput * forceMultiplier);
 }
 }
 }
}
