using UnityEngine;
using UnityEngine.XR.Interaction.Toolkit;

public class HandInteraction : MonoBehaviour
{
 [SerializeField] private XRController controller;
 [SerializeField] private LayerMask grabLayer;

 private XRGrabInteractable currentInteractable;
 private bool isGripPressed;
 private bool isClimbing;

 private void OnEnable()
 {
 controller.selectEntered.AddListener(OnSelectEntered);
 controller.selectExited.AddListener(OnSelectExited);
 controller.inputDevice.TryGetFeatureValue(CommonUsages.gripButton, out isGripPressed);
 }

 private void OnDisable()
 {
 controller.selectEntered.RemoveListener(OnSelectEntered);
 controller.selectExited.RemoveListener(OnSelectExited);
 }

 private void Update()
 {
 if (isGripPressed && currentInteractable && !isClimbing)
 {
 isClimbing = currentInteractable is ClimbingHandHold;
 if (isClimbing)
 {
 // Start climbing
 ClimbingHandHold climbingHold = currentInteractable.GetComponent<ClimbingHandHold>();
 climbingHold.StartClimbing(controller.inputDevice);
 }
 else
 {
 // Grab the interactable
 currentInteractable.attachTransform.position = controller.transform.position;
 currentInteractable.attachTransform.rotation = controller.transform.rotation;
 currentInteractable.transform.SetParent(controller.transform);
 currentInteractable.transform.localPosition = Vector3.zero;
 currentInteractable.transform.localRotation = Quaternion.identity;
 currentInteractable.interactionLayerMask = grabLayer;
 }
 }
 else if (!isGripPressed && currentInteractable)
 {
 if (isClimbing)
 {
 // Stop climbing
 ClimbingHandHold climbingHold = currentInteractable.GetComponent<ClimbingHandHold>();
 climbingHold.StopClimbing();
 }
 else
 {
 // Release the interactable
 currentInteractable.transform.SetParent(null);
 currentInteractable.interactionLayerMask = LayerMask.GetMask("Default");
 }
 currentInteractable = null;
 isClimbing = false;
 }
 }

 private void OnSelectEntered(XRBaseInteractable interactable)
 {
 currentInteractable = interactable as XRGrabInteractable;
 }

 private void OnSelectExited(XRBaseInteractable interactable)
 {
 if (currentInteractable == interactable)
 {
 currentInteractable = null;
 isClimbing = false;
 }
 }
}
