 int w;
 cin >> w;
 if (w == 0) {
 adj_matrix[i][j] = INT_MAX;
 } else {
 adj_matrix[i][j] = w;
 }
 }
 }
 return 0;
}
```
In this example, the input format is expected to be:


```python
