Here's an implementation of finding all pair shortest paths in an unweighted graph using BFS in C++:


```css
#include <iostream>
#include <vector>
#include <queue>
using namespace std;

const int MAX = 100005;
vector<int> g[MAX];
int dist[MAX][MAX];
int n, m;

void bfs(int start) {
 queue<int> q;
 q.push(start);
 dist[start][start] = 0;

 while (!q.empty()) {
 int u = q.front();
 q.pop();

 for (int i = 0; i < g[u].size(); i++) {
 int v = g[u][i];
 if (dist[start][v] == -1) {
 dist[start][v] = dist[start][u] + 1;
 q.push(v);
 }
 }
 }
}

int main() {
 cin >> n >> m;

 for (int i = 0; i < m; i++) {
 int u, v;
 cin >> u >> v;
 g[u].push\_back(v);
 g[v].push\_back(u);
 }

 memset(dist, -1, sizeof dist);
 for (int i = 1; i <= n; i++) {
 bfs(i);
 }

 return 0;
}
```
In this implementation, we first initialize the distance between all pairs as -1, which represents that they are not connected. The `bfs` function takes a starting node and runs BFS on the graph to find the shortest paths from the starting node to all other nodes. After running the BFS function for each node, the `dist` matrix will contain the distances between all pairs of nodes.

