import { ConfigContext } from '../config-provider';
import { cloneElement, isValidElement } from '../_util/reactNode';
import useStyle from './style/index';

const SpinSizes = ['small', 'default', 'large'] as const;
export type SpinSize = typeof SpinSizes[number];
export type SpinIndicator = React.ReactElement;

export interface SpinProps {
  prefixCls?: string;
  className?: string;
  rootClassName?: string;
  spinning?: boolean;
  style?: React.CSSProperties;
  size?: SpinSize;
  tip?: React.ReactNode;
  delay?: number;
  wrapperClassName?: string;
  indicator?: SpinIndicator;
  children?: React.ReactNode;
}

export interface SpinClassProps extends SpinProps {
  hashId: string;
  spinPrefixCls: string;
}

export type SpinFCType = React.FC &amp; {
  setDefaultIndicator: (indicator: React.ReactNode) =&gt; void;
};

// Render indicator
let defaultIndicator: React.ReactNode = null;

function renderIndicator(prefixCls: string, props: SpinClassProps): React.ReactNode {
  const { indicator } = props;
  const dotClassName = `${prefixCls}-dot`;

  // should not be render default indicator when indicator value is null
  if (indicator === null) {
    return null;
  }

  if (isValidElement(indicator)) {
    return cloneElement(indicator, {
      className: classNames(indicator.props.className, dotClassName),
    });
  }

  if (isValidElement(defaultIndicator)) {
    return cloneElement(defaultIndicator, {
      className: classNames(defaultIndicator.props.className, dotClassName),
    });
  }

  return (
    <span>
      <i>
      <i>
      <i>
      <i>
    </i></i></i></i></span>
  );
}

function shouldDelay(spinning?: boolean, delay?: number): boolean {
  return !!spinning &amp;&amp; !!delay &amp;&amp; !isNaN(Number(delay));
}

const Spin: React.FC = (props) =&gt; {
  const {
    spinPrefixCls: prefixCls,
    spinning: customSpinning = true,
    delay = 0,
    className,
    rootClassName,
    size = 'default',
    tip,
    wrapperClassName,
    style,
    children,
    hashId,
    ...restProps
  } = props;

  const [spinning, setSpinning] = React.useState(
    () =&gt; customSpinning &amp;&amp; !shouldDelay(customSpinning, delay),
  );

  React.useEffect(() =&gt; {
    if (customSpinning) {
      const showSpinning = debounce(delay, () =&gt; {
        setSpinning(true);
      });
      showSpinning();
      return () =&gt; {
        showSpinning?.cancel?.();
      };
    }

    setSpinning(false);
  }, [delay, customSpinning]);

  const isNestedPattern = React.useMemo(() =&gt; typeof children !== 'undefined', [children]);

  const { direction } = React.useContext(ConfigContext);

  const spinClassName = classNames(
    prefixCls,
    {
      [`${prefixCls}-sm`]: size === 'small',
      [`${prefixCls}-lg`]: size === 'large',
      [`${prefixCls}-spinning`]: spinning,
      [`${prefixCls}-show-text`]: !!tip,
      [`${prefixCls}-rtl`]: direction === 'rtl',
    },
    className,
    rootClassName,
    hashId,
  );

  const containerClassName = classNames(`${prefixCls}-container`, {
    [`${prefixCls}-blur`]: spinning,
  });

  // fix https://fb.me/react-unknown-prop
  const divProps = omit(restProps, ['indicator', 'prefixCls']);

  const spinElement: React.ReactNode = (
    <div>
      {renderIndicator(prefixCls, props)}
      {tip ? <div>{tip}</div> : null}
    </div>
  );

  if (isNestedPattern) {
    return (
      <div>
        {spinning &amp;&amp; <div>{spinElement}</div>}
        <div>
          {children}
        </div>
      </div>
    );
  }
  return spinElement;
};

const SpinFC: SpinFCType = (props) =&gt; {
  const { prefixCls: customizePrefixCls } = props;
  const { getPrefixCls } = React.useContext(ConfigContext);

  const spinPrefixCls = getPrefixCls('spin', customizePrefixCls);

  const [wrapSSR, hashId] = useStyle(spinPrefixCls);

  const spinClassProps: SpinClassProps = {
    ...props,
    spinPrefixCls,
    hashId,
  };
  return wrapSSR();
};

SpinFC.setDefaultIndicator = (indicator: React.ReactNode) =&gt; {
  defaultIndicator = indicator;
};

if (process.env.NODE_ENV !== 'production') {
  SpinFC.displayName = 'Spin';
}

export default SpinFC;

