 val a = random.nextInt(10) - 5
 val b = random.nextInt(10) - 5

 // Calculate the sum and product of a and b
 val sum = a + b
 val product = a * b

 // Construct the expression
 val expression = "x^2 ${if (sum >= 0) "+" else "-"} (${Math.abs(sum)})x ${if (product >= 0) "+" else "-"} ${Math.abs(product)}"

 // Write the expression and answer to the respective files
 questionsWriter.println(expression)
 answersWriter.println("($a, $b)")
 }

 // Close the questions and answers files
 questionsWriter.close()
 answersWriter.close()
}
```
