 const validationResult = validateUser(req.body);
 const result = await fold(
 (errors) => {
 console.error(errors);
 res.status(400).json(errors);
 },
 (data) => {
 const { name, email } = req.body;
 const result = await fold(
 (err) => {
 console.error(err);
 res.status(500).json({ message: 'An error occurred' });
 },
 (data) => {
 res.json(data);
 }
