To generate a spec for the entire API, you can create a new command that iterates through the route definitions and uses the `requestSpec()` and `responseSpec()` methods on the associated Form Request and Resource Response objects to build the OpenAPI spec.


```
use Illuminate\Console\Command;
use Illuminate\Support\Facades\Route;

class GenerateOpenApiSpec extends Command
{
 protected $signature = 'openapi:generate';

 protected $description = 'Generate the OpenAPI spec for the entire API';

 public function handle(): void
 {
 $spec = [];

 // Iterate through the route definitions
 Route::getRoutes()->getIterator()->each(function (Route $route) use (&$spec) {
 $requestClass = $route->getAction('request');
 $responseClass = $route->getAction('response');

 if (is\_subclass\_of($requestClass, FormRequest::class) && is\_subclass\_of($responseClass, JsonResource::class)) {
 // Use the requestSpec() and responseSpec() methods on the Form Request and Resource Response objects to build the spec
 $spec[$route->uri()] = [
 'method' => $route->methods()[0],
 'request' => (new $requestClass())->requestSpec(),
 'response' => (new $responseClass())->responseSpec(),
 ];
 }
 });

 // Save the generated spec to a file
 file\_put\_contents(base\_path('openapi.json'), json\_encode($spec, JSON_PRETTY_PRINT));

 $this->info('OpenAPI spec generated successfully');
 }
}
